// Asset registry: one entry per art file in src/assets/art, per code-drawn picture, per synthesized sound and per
// code-only effect. Generated by tools/gen-asset-registry.mjs (re-running keeps your status/notes edits); edit
// 'status' by hand to promote an asset (placeholder -> draft -> final). Checked by tests/assetRegistry.test.ts.
// See docs/art/ASSET_HUB.md.

export type AssetCategory = 'units' | 'monsters-bosses' | 'board-cells' | 'projectiles-impacts' | 'merge-cascade-fx' | 'ui-buttons' | 'ui-panels' | 'ui-bars-stars' | 'popups-menus' | 'tabs-icons' | 'currency-rewards' | 'crates' | 'backgrounds' | 'screw-yard' | 'power-tools' | 'fonts' | 'sounds';
export type AssetStatus = 'placeholder' | 'draft' | 'final';
export type AssetSource = 'chatgpt' | 'hand' | 'code' | 'synth';

export interface AssetEntry {
  id: string;
  category: AssetCategory;
  subcategory: string;
  name: string;
  /** Repo-relative path under src/assets/art, or 'code-drawn' for pictures/sounds/effects made in code. */
  file: string;
  status: AssetStatus;
  source: AssetSource;
  /** Unit rank (1..) for units. */
  rank?: number;
  notes: string;
}

export const ASSET_CATEGORIES: AssetCategory[] = ['units', 'monsters-bosses', 'board-cells', 'projectiles-impacts', 'merge-cascade-fx', 'ui-buttons', 'ui-panels', 'ui-bars-stars', 'popups-menus', 'tabs-icons', 'currency-rewards', 'crates', 'backgrounds', 'screw-yard', 'power-tools', 'fonts', 'sounds'];
export const ASSET_STATUSES: AssetStatus[] = ['placeholder', 'draft', 'final'];

export const assetsIn = (category: AssetCategory) => ASSET_REGISTRY.filter((a) => a.category === category);
export const assetById = (id: string) => ASSET_REGISTRY.find((a) => a.id === id);

